from mk import *
from lib import fbd
STRICT["on"] = True

def car(forces, pos, note, alt):
    return lambda: fbd(forces, alt, positive=pos, body="block", surface="below", note=note)

E(id="bagrut-2014-q2", year=2014, label="2014 שאלה 2", topic="dynamics", sub="dyn-friction", diff=3,
  stem=r"תפקיד המנוע הוא לסובב את הגלגלים של המכונית.",
  parts=[
    P("א", r"מכונית מתחילה לנסוע. איזה כוח חיצוני פועל על המכונית בכיוון התנועה וגורם למהירות שלה לגדול? מה מפעיל את הכוח הזה?", OPEN, ["fbd", "understanding"], [
        D(r"תרשים הכוחות על המכונית כשהיא מתחילה לנסוע", car([("fₛ", 0, 0.8), ("N", 90, 1.0), ("mg", -90, 1.0)], 0, "מאיצה",
            "תרשים כוחות על המכונית: חיכוך סטטי של הכביש קדימה, בכיוון התנועה, הכוח הנורמלי כלפי מעלה וכוח הכובד כלפי מטה. הכיוון החיובי הוא כיוון התנועה")),
        S(r"הכוח", r"הגלגל דוחף את הכביש אחורה בנקודת המגע. לפי החוק השלישי, הכביש דוחף את הגלגל קדימה. הצמיג לא מחליק על הכביש, ולכן זה חיכוך סטטי", r"\vec F_{1,2} = -\vec F_{2,1}", eq=r"\vec F_{1,2} = -\vec F_{2,1}"),
    ], r"כוח החיכוך הסטטי בין הצמיגים לכביש, שהכביש מפעיל", key=r"חיכוך סטטי, הכביש מפעיל"),
    P("ב", r"כשיש קרח על הכביש, המכונית לא יכולה להגיע לתאוצה שהייתה מגיעה אליה בלי קרח. הסבירו מדוע.", OPEN, ["principle"], [
        S(r"החיכוך הסטטי המרבי", r"על קרח מקדם החיכוך קטן, ולכן הכוח המרבי שהכביש יכול לתת קטן", r"f_s \le \mu_s N = \mu_s mg", eq=r"f_s \le \mu_s N"),
        S(r"משוואת כוחות", r"החיכוך הוא הכוח היחיד בכיוון התנועה. מחלקים במסה", r"f_s = ma \;\Rightarrow\; a \le \mu_s g", eq=r"\Sigma\vec F = m\vec a"),
    ], r"החיכוך המרבי על קרח קטן, ולכן גם התאוצה המרבית קטנה"),
    P("ג", r"מכונית נוסעת במהירות של $90\,\text{km/h}$ ובולמת. בזמן הבלימה הגלגלים ננעלים, והמכונית מחליקה עד שהיא נעצרת. (1) מה מרחק הבלימה, מתחילת הבלימה עד העצירה, כשיש קרח על הכביש ומקדם החיכוך הקינטי $\mu_k = 0.1$? (2) מה מרחק הבלימה כשאין קרח, ומקדם החיכוך הקינטי $\mu_k = 0.8$? (3) לפי התשובות, הסבירו מדוע סוגרים לתנועה כבישים שהצטבר עליהם קרח.",
      multi((r"(1) עם קרח", 312.5, "m"), (r"(2) בלי קרח", 39.0625, "m")), ["principle", "units", "algebra"], [
        X(r"הכיוון החיובי הוא כיוון הנסיעה. בוחרים אותו, כי השאלה לא קבעה כיוון."),
        D(r"תרשים הכוחות על המכונית בזמן הבלימה", car([("fₖ", 180, 0.7), ("N", 90, 1.0), ("mg", -90, 1.0)], 0, "מחליקה ומאטה",
            "תרשים כוחות על המכונית בבלימה: חיכוך קינטי אחורה, נגד התנועה, הכוח הנורמלי כלפי מעלה וכוח הכובד כלפי מטה. הכיוון החיובי הוא כיוון הנסיעה")),
        S(r"ממירים את המהירות", r"מחלקים בשלוש נקודה שש", r"v_0 = \frac{90}{3.6} = 25\,\text{m/s}"),
        S(r"משוואת כוחות", r"בכיוון החיובי לא פועל אף כוח. נגדו החיכוך הקינטי. הכוח הנורמלי שווה לכובד", r"0 - f_k = ma", eq=r"f_k = \mu_k N"),
        S(r"מציבים את החיכוך", r"הכוח הנורמלי שווה לכובד", r"f_k = \mu_k N = \mu_k mg \;\Rightarrow\; -\mu_k mg = ma"),
        S(r"מחלקים את משוואת הכוחות במסה", r"ההאטה לא תלויה במסת המכונית", r"a = -\mu_k g"),
        S(r"משוואת המהירות בלי זמן", r"עד שהמכונית נעצרת", r"0^2 = v_0^2 + 2(-\mu_k g)\,d \;\Rightarrow\; d = \frac{v_0^2}{2\mu_k g}", eq=r"v^2 = v_0^2 + 2a(x - x_0)"),
        S(r"(1) עם קרח", r"מציבים את מקדם החיכוך הקטן", r"d_1 = \frac{25^2}{2 \cdot 0.1 \cdot 10} = 312.5\,\text{m}"),
        S(r"(2) בלי קרח", r"מציבים את מקדם החיכוך הגדול", r"d_2 = \frac{25^2}{2 \cdot 0.8 \cdot 10} \approx 39.06\,\text{m}"),
        S(r"(3) משווים", r"מרחק הבלימה על קרח גדול פי שמונה, ונהג לא יספיק לעצור בזמן", r"\frac{d_1}{d_2} = \frac{0.8}{0.1} = 8"),
    ], r"(1) $312.5\,\text{m}$. (2) $\approx 39.06\,\text{m}$. (3) על קרח מרחק הבלימה גדול פי $8$", key=r"312.5 m ; 39.0625 m"),
    P("ד", r"מכונית שמסתה $1000\,\text{kg}$ נוסעת קדימה. ברגע מסוים פועל עליה כוח של $1200\,\text{N}$ בכיוון התנועה, והשקול של כל כוחות החיכוך נגד כיוון התנועה הוא $400\,\text{N}$. מה התאוצה של המכונית ברגע הזה?", num(0.8, "m/s^2"), ["principle"], [
        D(r"תרשים הכוחות על המכונית", car([("F", 0, 1.1), ("f", 180, 0.45), ("N", 90, 1.0), ("mg", -90, 1.0)], 0, "מאיצה",
            "תרשים כוחות על המכונית: כוח של 1200 ניוטון בכיוון התנועה, כוחות חיכוך של 400 ניוטון נגדו, הכוח הנורמלי והכובד. הכיוון החיובי הוא כיוון התנועה")),
        S(r"משוואת כוחות", r"בכיוון החיובי הכוח המניע, ונגדו החיכוך", r"1200 - 400 = 1000\,a", eq=r"\Sigma\vec F = m\vec a"),
        S(r"מחלקים את משוואת הכוחות במסה", r"התאוצה חיובית, בכיוון התנועה", r"a = \frac{800}{1000} = 0.8\,\text{m/s}^2"),
    ], r"$0.8\,\text{m/s}^2$", key=r"a=0.8 m/s^2"),
    P("ה", r"הכוח שפועל על מכונית בכיוון התנועה נותן לה תאוצה, ולכאורה מכונית יכולה להגיע לכל מהירות, אם רק תאיץ מספיק זמן. הסבירו מדוע בכל זאת לכל מכונית יש מהירות מרבית, שהיא לא יכולה לעבור בנסיעה על כביש אופקי. (בסעיף הזה פועלת על המכונית גם התנגדות האוויר, שגדלה ככל שהמהירות גדלה.)", OPEN, ["principle"], [
        S(r"משוואת כוחות", r"בכיוון החיובי הכוח המניע, ונגדו התנגדות האוויר", r"F - f(v) = ma", eq=r"\Sigma\vec F = m\vec a"),
        S(r"התנגדות האוויר גדלה", r"ככל שהמהירות גדלה, ההתנגדות מתקרבת לכוח המרבי שהמכונית יכולה לקבל מהכביש", r"v\ \uparrow \;\Rightarrow\; f(v)\ \uparrow \;\Rightarrow\; a\ \downarrow"),
        S(r"מהירות מרבית", r"כשהם שווים, הכוח השקול אפס, ואין עוד תאוצה", r"F_{\max} - f(v_{\max}) = 0"),
    ], r"התנגדות האוויר גדלה עם המהירות עד שהיא משתווה לכוח המניע"),
  ],
  concepts=["חיכוך סטטי כמניע", "חיכוך קינטי בבלימה", "מרחק בלימה", "התנגדות אוויר ומהירות מרבית"],
  summary=r"מה באמת דוחף מכונית קדימה, למה קרח מסוכן, ולמה יש למכונית מהירות מרבית.",
  review="הנחה שלי.\nסעיף ג הוא סעיף אחד, כמו במקור, עם שתי תיבות, וההסבר של חלק (3) בפתרון.\nמה לבדוק: רק לאשר.")
